update country_flag_history set date_end = '1707-05-01', label_fr = 'Union Flag de Jacques Ier (1606-1707)', label_en = 'Union Flag of James I (1606–1707)', notes_fr = 'Le 12 avril 1606, Jacques Ier, roi d''Angleterre et d''Écosse, fait superposer les croix de saint Georges et de saint André pour les navires de ses deux royaumes.', notes_en = 'On 12 April 1606 James I, King of England and Scotland, had the crosses of St George and St Andrew combined for the ships of his two kingdoms.', image_url = '/flags/history/gb-0000.svg' where id = 2251 and iso_code = 'gb';
update country_flag_history set date_start = '1707-05-01', date_end = '1801-01-01', label_fr = 'Royaume de Grande-Bretagne (1707-1801)', label_en = 'Kingdom of Great Britain (1707–1801)', notes_fr = 'L''Acte d''Union de 1707 fait de l''Union Flag le drapeau du nouveau royaume de Grande-Bretagne ; la croix de saint Patrick n''y figure pas encore.', notes_en = 'The 1707 Act of Union made the Union Flag the flag of the new Kingdom of Great Britain; St Patrick''s cross was not yet part of it.' where id = 2373 and iso_code = 'gb';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('gb', '/flags/history/gb-1649.svg', '1649-05-19', '1651-01-01', 'Commonwealth d''Angleterre (1649-1651)', 'Commonwealth of England (1649–1651)', 'Après l''exécution de Charles Ier, la république remplace l''Union Flag par la croix de saint Georges accolée à la harpe irlandaise.', 'After Charles I was executed, the republic replaced the Union Flag with St George''s cross set beside the Irish harp.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('gb', '/flags/history/gb-1651.svg', '1651-01-01', '1658-09-03', 'Commonwealth (1651-1658)', 'Commonwealth (1651–1658)', 'Drapeau écartelé des croix de saint Georges et de saint André, utilisé sous le Commonwealth et le protectorat d''Oliver Cromwell.', 'A flag quartering the crosses of St George and St Andrew, used under the Commonwealth and Oliver Cromwell''s Protectorate.');
